Write standard CSS rules implementing this design specification. Each outer key is a selector; each inner key is a valid CSS property and its value is the desired styling. One rule per selector, colon between property/value, semicolon after EVERY declaration. No JSON, JavaScript, explanations or extra rules in the output. Design specification:
{
  ".viewer": {
    "display": "flex",
    "flex-direction": "column",
    "gap": "12px",
    "padding": "16px",
    "min-height": "0",
    "min-width": "0",
    "background": "#171a20"
  },
  ".viewer-surface": {
    "position": "relative",
    "flex": "1",
    "min-height": "0",
    "display": "flex",
    "background": "#08090b"
  },
  "#preview": {
    "width": "100%",
    "height": "100%",
    "object-fit": "contain"
  },
  "#textOverlay": {
    "position": "absolute",
    "bottom": "10%",
    "left": "0",
    "right": "0",
    "text-align": "center",
    "font-size": "24px",
    "color": "white",
    "text-shadow": "0 1px 4px black",
    "pointer-events": "none"
  },
  ".transport": {
    "display": "flex",
    "gap": "12px"
  },
  "#seekInput": {
    "flex": "1",
    "min-width": "0"
  }
}

Write standard CSS implementing this design specification. Outer keys are selectors, inner keys are CSS properties with desired values. Wrap the mobile specification in its @media block when present. Separate each declaration with a semicolon. Output CSS only, not JSON/JS or explanations. Specification:
{
  "button, a[download]": {
    "height": "32px",
    "padding": "6px 12px",
    "border": "1px solid #2b3038",
    "border-radius": "6px",
    "background": "#232831",
    "color": "#edf0f4"
  },
  "#exportBtn": {
    "background": "#72edc3",
    "color": "#0e1013"
  },
  "button:disabled, input:disabled": {
    "opacity": ".45"
  },
  "input": {
    "width": "100%",
    "min-width": "0",
    "background": "#171a20",
    "border": "1px solid #2b3038",
    "padding": "8px",
    "color": "inherit"
  },
  "[hidden]": {
    "display": "none !important"
  },
  ".error": {
    "color": "#f38181"
  },
  ".track-row": {
    "display": "flex"
  },
  ".track-label": {
    "width": "70px"
  },
  ".track-lane": {
    "position": "relative",
    "flex": "1",
    "height": "32px",
    "overflow": "hidden"
  },
  ".video-clip, .text-clip": {
    "position": "absolute",
    "height": "28px",
    "background": "#315f79",
    "overflow": "hidden",
    "text-overflow": "ellipsis",
    "white-space": "nowrap"
  },
  ".text-clip": {
    "background": "#72edc3",
    "color": "#0e1013"
  },
  ".playhead": {
    "position": "absolute",
    "top": "0",
    "bottom": "0",
    "width": "2px",
    "background": "#72edc3"
  }
}

Write standard CSS implementing this design specification. Outer keys are selectors, inner keys are CSS properties with desired values. Wrap the mobile specification in its @media block when present. Separate each declaration with a semicolon. Output CSS only, not JSON/JS or explanations. Specification:
{
  "@media (max-width:700px)": {
    "body": {
      "height": "auto",
      "min-height": "100dvh",
      "display": "flex",
      "flex-direction": "column",
      "overflow": "visible"
    },
    ".stage": {
      "display": "flex",
      "flex-direction": "column"
    },
    ".viewer": {
      "order": "1"
    },
    ".library": {
      "order": "2"
    },
    ".inspector": {
      "order": "3"
    },
    ".viewer-surface": {
      "flex": "none",
      "aspect-ratio": "16/9",
      "min-height": "180px"
    },
    "#preview": {
      "max-height": "300px"
    },
    ".topbar": {
      "flex-wrap": "wrap",
      "min-height": "52px",
      "padding": "12px"
    },
    ".library, .viewer, .inspector, .timeline-panel": {
      "max-width": "100%",
      "min-width": "0"
    },
    ".timeline-panel": {
      "min-height": "180px"
    }
  }
}
